/* @lc app=leetcode id=2386 lang=kotlin */ class Solution { fun kSum(nums: IntArray, k: Int): Long = nums.map { it.toLong() }.let { nl -> nl.filter { it > 0 }.sumOf { it }.let { maxSum -> nl.map { kotlin.math.abs(it) }.sorted().let { sortedAbs -> if (k == 1) maxSum else java.util.PriorityQueue<kotlin.Pair<Long, Int>>(compareBy { it.first }).apply { add(sortedAbs[0] to 0) }.let { pq -> (1 until k).map { pq.poll().let { (sum, i) -> sum.also { if (i + 1 < sortedAbs.size) { pq.add(sum + sortedAbs[i + 1] to i + 1).also { pq.add(sum + sortedAbs[i + 1] - sortedAbs[i] to i + 1) } } } } }.last().let { maxSum - it } } } } } }